CREATE TABLE CORE.T_AGG_PROMOTION_SALES_DAILY_2 (
   WSHOP_CD                            VARCHAR(5)      NOT NULL COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer.The webshop is defined per political country_2 and is run by an Lidl Digital Country_2',
   PROMO_ID                            NUMBER(38, 0)   NOT NULL COMMENT 'An identifier from source system to uniqly identify the promotion',
   PROD_VARIANT_SID                    NUMBER          NOT NULL COMMENT 'Ordered product',
   CUST_ORDER_DT                       DATE            NOT NULL COMMENT 'The date when order was made',
   PROMO_START_DT                      DATE            COMMENT 'Start date of the product promotion in stationary business',
   PROMO_SALE_START_DT                 DATE            COMMENT 'Date when sales_2 of promotional goods starts',
   IS_SPECIAL_ANALYSIS_FG              BOOLEAN         COMMENT 'This flag is true if the customer order date is between analysis start date and analysis end date, otherwise is false which means outside this time range. The flag will hold null as value If the analysis dates are null, which means no specific analysis period is defined for a promotion type happening on a certain country_2',
   CURR_CD                             VARCHAR(5)      COMMENT 'Currency code in which order has been payed',
   PROD_PRICE_NET_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Original (listed) net price of a product in local currency',
   PROD_PRICE_GROSS_LOCAL_VAL          NUMBER(38, 5)   COMMENT 'Order gross price in local currency',
   COGS_PRICE_NET_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Cost-of-Goods-sold, short: CoGs. Needed for calc of margin (= revenue - cogs )',
   PROD_QTY                            NUMBER(38, 5)   COMMENT 'Quantity of a particular product ordered',
   CANCEL_PROD_PRICE_NET_LOCAL_VAL     NUMBER(38, 5)   COMMENT 'Original (listed) net price of a product in local currency',
   CANCEL_PROD_PRICE_GROSS_LOCAL_VAL   NUMBER(38, 5)   COMMENT 'Order gross price of cancelled products in local currency',
   CANCEL_PROD_QTY                     NUMBER(38, 5)   COMMENT 'Quantity of a particular product ordered',
   RETURN_PROD_PRICE_NET_LOCAL_VAL     NUMBER(38, 5)   COMMENT 'Original (listed) net price of a product in local currency',
   RETURN_PROD_PRICE_GROSS_LOCAL_VAL   NUMBER(38, 5)   COMMENT 'Order gross price of returned products in local currency',
   RETURN_PROD_QTY                     NUMBER(38, 5)   COMMENT 'Quantity of a particular product ordered',
   TOTAL_PROD_PRICE_NET_LOCAL_VAL      NUMBER(38, 5)   COMMENT 'Total original (listed) net price of a product in local currency',
   TOTAL_PROD_PRICE_GROSS_LOCAL_VAL    NUMBER(38, 5)   COMMENT 'Order gross price excluding the cancellations and returns in local currency',
   TOTAL_PROD_QTY                      NUMBER(38, 5)   COMMENT 'Total quantity of a particular product ordered',
   PROMO_SALE_CLUSTER_CD               NUMBER          COMMENT 'A code for aggregation of sales_2 orders assigned to a promotion based on the customer order date',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   AVAIL_LVL_CD                        VARCHAR(5)      COMMENT 'Indicator code for availability (1, Online ausverkauft; 2, Online in Kürze; 3, Bestellbar; Null, Offline)',
   PROD_ORDERABLE_LVL_CD               VARCHAR(5)      COMMENT 'Indicator code. It shows if a product is orderable, soon orderable, or not orderable. It is derived from multiple indicators, like stock_indicator, display_indicator, online_indicator',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
   SRC_TABLE_NAME                      VARCHAR(100)    COMMENT 'The name of the source tables',
   CONSTRAINT PK_T_AGG_PROMOTION_SALES_DAILY PRIMARY KEY (PROMO_ID, PROD_VARIANT_SID, CUST_ORDER_DT) NOT ENFORCED
 )  COMMENT= 'The fact that analises the quantity of goods sold since beginning of promotion';